var e={sito:{nome:`Clepsi`,titolo:`Clepsi · Il margine di ogni commessa, per studi di architettura e ingegneria`,descrizione:`Clepsi dice agli studi di architettura e ingegneria come chiuderà ogni commessa. Ogni sera due tap, niente timer, niente timesheet. Prova l'app gratis.`,saltaAlContenuto:`Vai al contenuto`,immagineAlt:`Una dipendente al bar, la sera: sul telefono la domanda di Clepsi con mattina e pomeriggio`},menu:{home:`Clepsi, torna all'inizio`,come:`Come funziona`,domande:`Domande`,prova:`Prova l'app`,principale:`Principale`,apri:`Menu`,apriEtichetta:`Apri il menu`,chiudiEtichetta:`Chiudi il menu`,funzioni:`Funzioni`,tutteFunzioni:`Tutte le funzioni`,vociFunzioni:[{icona:`previsione`,titolo:`Previsione del margine`,testo:`Come chiuderà ogni commessa, mentre la fai.`},{icona:`giornate`,titolo:`Budget in giornate`,testo:`Il compenso diviso in giornate, fase per fase.`},{icona:`varianti`,titolo:`Varianti da far pagare`,testo:`Il lavoro in più ha un valore e un riepilogo.`},{icona:`settimana`,titolo:`Settimana dello studio`,testo:`Chi ha lavorato su cosa, in una griglia.`},{icona:`bilancio`,titolo:`Bilancio di commessa`,testo:`Quanto ti ha reso ogni giornata.`},{icona:`fatica`,titolo:`Due tap la sera`,testo:`Niente timer e niente timesheet per il team.`}],risorse:`Risorse`,vociRisorse:[{chiave:`parcella`,titolo:`Calcola la parcella`,testo:`Il compenso secondo il D.M. 17/06/2016, gratis.`},{chiave:`costo`,titolo:`Costo della giornata`,testo:`Quanto costa davvero una giornata del tuo studio.`},{chiave:`gestionale`,titolo:`Gestionale per architetti`,testo:`Un gestionale che non ti chiede di segnare le ore.`},{chiave:`domande`,titolo:`Domande frequenti`,testo:`Prezzo, dati, come si comincia.`}]},primo:{titolo:`Sai quanto ti rende ogni commessa,`,titoloEvidenza:`mentre la fai.`,testo:`Ogni sera il team del tuo studio indica con due tap dove ha lavorato. Con Clepsi vedi come chiuderà ogni commessa, quando c'è ancora tempo per rimediare.`,entra:`Prova l'app`,esempio:`Guarda prima uno studio di esempio`,metaPrezzo:`Gratis, senza carta. I primi 100 studi di architettura e ingegneria pagano la metà il primo anno.`},problema:{occhiello:`Succede in ogni studio`,titolo:`Le giornate se ne vanno così. E nessuno le conta.`,scene:[{frase:`«Passo un attimo in cantiere.»`,conto:`Mezza giornata. Su nessuna commessa.`,nota:`Andata, sopralluogo, due parole con l'impresa, ritorno.`},{frase:`«È solo una piccola modifica.»`,conto:`Tre mezze giornate. Fatturate: zero.`,nota:`La variante chiesta il venerdì sera, tanto è una cosa veloce.`},{frase:`«Pensavo ci guadagnassimo.»`,conto:`34 giornate, ne avevi previste 27.`,nota:`Te ne accorgi quando la parcella è già stata incassata e spesa.`}]},timesheet:{occhiello:`Perché nessuno lo sa`,titolo:`Il timesheet negli studi non ha mai funzionato.`,punti:[{titolo:`Si compila il venerdì, a memoria.`,testo:`Nessuno ricorda se su un progetto ha passato tre ore o tre ore e venti.`},{titolo:`Il timer resta acceso.`,testo:`Parte al mattino, poi squilla il telefono, arriva un cliente, si va a pranzo.`},{titolo:`A nessuno piace sentirsi cronometrato.`,testo:`Chi disegna non timbra il cartellino, e ha ragione.`}]},niente:{fisso:`Niente`,parole:[`timer`,`timesheet`,`ore da segnare`,`fogli Excel`],ultima:`scuse.`,perLettori:`Niente timer, niente timesheet, niente ore da segnare, niente fogli Excel, niente scuse.`},risposta:{occhiello:`La risposta`,titolo:`Ogni sera, due tap.`,testo:`Alle 19 arriva una domanda sola: dove hai lavorato oggi? Mattina e pomeriggio. Dieci secondi, ovunque tu sia.`,fraseForte:`Le mezze giornate non si dimenticano.`,frase:`Tutti sanno dove hanno lavorato la mattina e dove il pomeriggio.`,pulsante:`Prova l'app`,telefono:{etichetta:`Esempio della domanda delle 19: la mattina su Villa Rossi, il pomeriggio su Scuola Brera`,app:`Clepsi`,domanda:`Com'è andata oggi?`,mattina:`Mattina`,pomeriggio:`Pomeriggio`,sigle:[`VRO`,`SBR`,`ULA`,`LNA`],sceltaMattina:`VRO`,sceltaPomeriggio:`SBR`,registra:`Registra la giornata`,registrata:`Giornata registrata`}},mattinaDopo:{occhiello:`La mattina dopo`,titolo:`Apri Clepsi. Sai già quale commessa sta perdendo.`,paragrafi:[`Le mezze giornate di tutti, confrontate con il compenso e con il costo di ogni persona. La previsione si ricalcola ogni sera.`,`Vedi quante giornate copre ancora il compenso, fase per fase. E il lavoro in più chiesto dal cliente finisce in un conto da presentargli.`]},dopoLe19:{etichetta:`Video: quattro persone dello studio, la sera, rispondono a Clepsi con due tap`,attivaAudio:`Attiva l'audio`,togliAudio:`Togli l'audio`,guarda:`Guarda il video`,seraPrecedente:`Sera precedente`,seraSuccessiva:`Sera successiva`,domanda:`Com'è andata oggi?`,mattina:`Mattina`,pomeriggio:`Pomeriggio`,tocca:`Tocca la commessa`,registrata:`Giornata registrata`,staseraTitolo:`Stasera nello studio`,registrateBreve:`{n} di 8 mezze giornate`,villaRossiBreve:`Villa Rossi +{n} ·`,copreBreve:`il compenso copre ancora 10 giornate.`,ruoli:[`Dipendente`,`Socio`,`Titolare`,`Collaboratore`]},cosaFa:{occhiello:`Cosa fa Clepsi`,titolo:`Tutto quello che oggi non sai delle tue commesse.`,voci:[{icona:`previsione`,titolo:`La previsione del margine.`,testo:`In attivo, margine stretto o in perdita: lo vedi mentre la fai, non quando è troppo tardi.`},{icona:`giornate`,titolo:`Il budget in giornate.`,testo:`Il compenso diventa giornate, fase per fase. Sai quante ne restano e quale fase è già oltre.`},{icona:`varianti`,titolo:`Le varianti da far pagare.`,testo:`Il lavoro in più non si perde: ha un valore, e a fine commessa il riepilogo per il cliente è pronto.`},{icona:`settimana`,titolo:`La settimana dello studio.`,testo:`Chi ha lavorato su cosa, in una griglia. Vedi quale commessa mangia il tempo delle altre.`},{icona:`bilancio`,titolo:`Il bilancio di ogni commessa.`,testo:`Quando chiudi, sai quanto ti ha reso ogni giornata. Il prossimo preventivo lo fai sui numeri.`},{icona:`fatica`,titolo:`Nessuna fatica per il team.`,testo:`Due tap la sera e un promemoria se ci si dimentica. I collaboratori non vedono mai un importo.`}]},lunedi:{etichetta:`Esempio della schermata del titolare: quattro commesse con il loro stato`,quando:`Lunedì mattina`,sintesi:`Uffici Lambrate è in perdita. Scuola Brera ha il margine stretto.`,sotto:`Villa Rossi è in attivo, Loft Navigli è appena iniziata. Ultimo aggiornamento: ieri alle 21.`,commesse:[{sigla:`VRO`,nome:`Villa Rossi`,colore:`#D4FF3A`,stato:`attivo`,riga:`Il compenso copre ancora 10 giornate`},{sigla:`SBR`,nome:`Scuola Brera`,colore:`#9B8CFF`,stato:`stretto`,riga:`Margine previsto 11% · fase definitiva oltre budget`},{sigla:`ULA`,nome:`Uffici Lambrate`,colore:`#6FD3FF`,stato:`perdita`,riga:`Già 3 giornate oltre il compenso`},{sigla:`LNA`,nome:`Loft Navigli`,colore:`#FF9ECF`,stato:`iniziata`,riga:`Ancora poche sere di risposte per dirlo`}],stati:{attivo:`In attivo`,stretto:`Margine stretto`,perdita:`In perdita`,iniziata:`Appena iniziata`}},fineCommessa:{occhiello:`A fine commessa`,titolo:`Ogni commessa chiusa ti insegna il prossimo preventivo.`,testo:`Clepsi fa il bilancio: quanto ti ha reso ogni giornata, quante sono finite in varianti non fatturate, come va rispetto alle altre dello stesso tipo.`,scheda:{etichetta:`Esempio del bilancio di una commessa chiusa: Uffici Lambrate`,nome:`Uffici Lambrate`,stato:`chiusa`,righe:[{valore:`34`,dopo:`su 27 previste`,testo:`Giornate lavorate`},{valore:`265 €`,dopo:`costo medio 320 €`,testo:`Resa per giornata`,sotto:!0},{valore:`6 giornate`,dopo:``,testo:`Varianti non fatturate`},{valore:`290 €`,dopo:`a giornata`,testo:`Ristrutturazioni dello studio, in media`}]}},primaChe:{titolo:`Prima che tu lo chieda.`,voci:[{titolo:`Non è un modo per controllare.`,testo:`Nessun timer e nessuna ora da segnare. I collaboratori indicano solo la commessa e non vedono mai un importo.`},{titolo:`Puoi iniziare da solo.`,testo:`Provi su una commessa e inviti il team quando ti ha convinto.`},{titolo:`Oggi è gratis.`,testo:`Poi da 19 € al mese per studio, IVA esclusa. I primi 100 studi pagano la metà il primo anno.`},{titolo:`Nata in uno studio.`,testo:`Da chi a fine commessa voleva sapere se ci aveva guadagnato davvero. La usiamo ogni sera.`}]},comincia:{occhiello:`Come si comincia`,titolo:`Stasera la prima domanda. Tra una settimana, la prima previsione.`,passi:[{titolo:`Adesso, due minuti.`,testo:`Crei lo studio e una commessa, anche dalla parcella calcolata qui.`},{titolo:`Stasera alle 19.`,testo:`Rispondi con due tap. Puoi iniziare da solo.`},{titolo:`Venerdì.`,testo:`Indichi a che punto sono le fasi e cosa era lavoro in più.`},{titolo:`Tra una settimana.`,testo:`Vedi come chiuderà la commessa. Poi inviti il team.`}],computer:{forte:`Dal computer`,testo:`gestisci commesse, persone e previsioni.`},telefono:{forte:`Dal telefono`,testo:`il team risponde la sera, in dieci secondi.`}},seneca:{latino:`Omnia aliena sunt, tempus tantum nostrum est.`,traduzione:`Tutto è d'altri. Solo il tempo è nostro.`,fonte:`Seneca, Lettere a Lucilio`},racconto:{occhiello:`Perché Clepsi`,etichetta:`Perché Clepsi: un video in sei scene sul tempo di uno studio, con le frasi di Seneca`,pausa:`Metti in pausa il video`,riproduci:`Riproduci il video`,vaiAllaScena:`Vai alla scena {n}: {frase}`,entra:`Prova l'app`},domande:{occhiello:`Domande`,titolo:`Quello che ci chiedono gli studi.`,elenco:[{domanda:`È un modo per controllare chi lavora?`,risposta:`No. Niente timer, niente ore, niente posizione: ognuno indica solo su quale commessa ha lavorato la mattina e su quale il pomeriggio. I collaboratori vedono le proprie giornate, non i compensi né i costi. Il capo commessa vede margine e giornate delle sue commesse, non i costi delle persone. Il costo di ogni persona lo vede solo chi amministra lo studio.`},{domanda:`Quanto costa?`,risposta:`Adesso Clepsi è gratis, senza carta. Poi un prezzo per studio, al mese, IVA esclusa: 19 € fino a 3 persone, 29 € da 4 a 10, 59 € da 11 a 25. Oltre, su misura. Con l'annuale due mesi sono gratis. I primi 100 studi pagano la metà il primo anno.`},{domanda:`Devo cambiare il modo in cui lavoriamo?`,risposta:`No. Crei le commesse con le loro fasi e i compensi, anche partendo dalla parcella calcolata qui, e inviti lo studio con un messaggio su WhatsApp o un'email. La sera stessa, alle 19, arriva la prima domanda.`},{domanda:`Clepsi pianifica il lavoro del team?`,risposta:`No, e non ti chiede di farlo. Clepsi guarda le giornate già lavorate e ti dice come chiuderà ogni commessa a questo ritmo. Chi fa cosa la settimana prossima lo decidi tu, con un'informazione in più.`},{domanda:`E se qualcuno si dimentica di rispondere?`,risposta:`Alle 21 arriva un promemoria. Si può rispondere anche nei due giorni successivi, e ognuno corregge le proprie giornate fino alla domenica.`},{domanda:`Funziona su iPhone, su Android e dal computer?`,risposta:`Sì. Chi amministra lo studio o segue una commessa può usare Clepsi anche dal browser del computer. La domanda della sera arriva sul telefono, iPhone o Android: per rispondere basta quello.`},{domanda:`Chi c'è dietro Clepsi?`,risposta:`Clepsi nasce dentro uno studio di architettura, da chi a fine commessa voleva sapere se ci aveva guadagnato davvero. E non voleva chiedere a nessuno di compilare un timesheet.`},{domanda:`Posso provarla adesso?`,risposta:`Sì. Funziona già, e ogni settimana la miglioriamo con gli studi che la usano. È gratis e non serve la carta. Le app per iPhone e Android arrivano sugli store più avanti; intanto si installa dal browser in un minuto.`}]},lista:{latino:`Collige et serva.`,titolo:`Provala con il tuo studio.`,testo:`Crei lo studio, inserisci una commessa e inviti il team: da stasera alle 19 arriva la domanda. È gratis, senza carta. I primi 100 studi pagano la metà il primo anno.`,pulsante:`Prova l'app`,esempio:`Guarda prima uno studio di esempio`},chiusura:{titolo:`Stasera alle 19, la prima domanda.`,testo:`Crei lo studio, inserisci una commessa, rispondi con due tap. È gratis, senza carta.`,pulsante:`Prova l'app`,esempio:`Guarda prima uno studio di esempio`,parcellaPrima:`Intanto, `,parcellaLink:`calcola la parcella della tua prossima commessa`,parcellaDopo:`: gratis, con le giornate che ti paga.`},piede:{instagram:`Clepsi su Instagram`,linkedin:`Clepsi su LinkedIn`,privacy:`Privacy`,cookie:`Cookie`,anno:`Clepsi · © 2026`,strumenti:`Strumenti gratuiti`,strumentiParcella:`Calcolo parcella`,strumentiCosto:`Quanto costa una giornata dello studio`,clepsi:`Clepsi`,gestionale:`Gestionale per studi di architettura`,privacyApp:`Privacy dell'app`},titolareTrattamento:{nome:`Stefano Morelli`,partitaIva:`IT02603120425`,email:`info@clepsi.it`},nonTrovata:{titolo:`Questa pagina non c'è.`,testo:`Forse il link è vecchio o incompleto. Da qui puoi tornare alla home o calcolare la parcella.`,home:`Torna alla home`,parcella:`Calcola la parcella`},parcella:JSON.parse(`{"reel":{"occhiello":"Poi, in Clepsi","titolo":"Dalla parcella alla commessa, con un tocco.","testo":"La parcella calcolata qui si apre nell'app già pronta: le voci scelte diventano le fasi della commessa, ognuna con le giornate che il compenso paga. Da quel momento vedi, sera dopo sera, se le giornate bastano."},"titoloPagina":"Calcolo parcella architetti e ingegneri {anno} · D.M. 17/06/2016 · Clepsi","descrizionePagina":"Calcolo gratuito della parcella e del compenso professionale di architetti e ingegneri: D.M. 17 giugno 2016 e D.Lgs. 36/2023 (allegato I.13), con spese, ribasso e le giornate che la parcella ti paga.","occhiello":"Calcolo parcella {anno} · Gratis, senza registrarti","titolo":"Calcola la parcella di architetti e ingegneri. Poi scopri quante giornate ti paga.","titoloEvidenza":"Poi scopri quante giornate ti paga.","picco":{"occhiello":"Il numero che nessun calcolatore ti dà","titolo":"Ti paga {giornate}.","dalla":"Dalla {n}ª in poi la commessa lavora in perdita.","forte":"Clepsi ti dice ogni sera quante ne hai già usate","dopo":", con due tap del tuo team.","pulsante":"Aprila in Clepsi","accanto":"La parcella diventa la tua prima commessa, con fasi e compensi già compilati."},"chiusura":{"titolo":"Stasera alle 19, la prima domanda.","testo":"Crei lo studio, apri questa parcella come prima commessa, rispondi con due tap. È gratis, senza carta.","pulsante":"Prova l'app"},"intro":"Il compenso professionale secondo il D.M. 17 giugno 2016, con tutte le prestazioni divise nelle fasi del Codice dei contratti (D.Lgs. 36/2023, allegato I.13). Scegli voce per voce. In fondo, il numero che nessun calcolatore ti dà: quante giornate di studio copre davvero.","opera":{"titolo":"L'opera","aiuto":"Una scheda per ogni categoria dell'opera (edilizia, strutture, impianti…), ognuna con il suo importo.","schede":"Categorie dell'opera","aggiungi":"+ Aggiungi una categoria","togli":"Togli questa categoria","importo":"Importo dei lavori di questa categoria (V)","categoria":"Categoria","destinazione":"Destinazione funzionale","identificazione":"Identificazione dell'opera","grado":"Grado di complessità G =","parametro":"Parametro base P = 0,03 + 10 / V","parametroEsp":"0,4","sotto25000":"Sotto i 25.000 € il parametro P resta quello di 25.000 € (art. 3 c. 5).","restauro":"Per verifica sismica, indagini sulle strutture e collaudo statico aggiungi una categoria Strutture: quelle voci valgono solo lì.","svuota":"Svuota i campi"},"prestazioni":{"titolo":"Le prestazioni","aiuto":"Apri una fase e spunta le voci che fai tu. Le fasi con almeno una voce diventeranno le fasi della commessa.","scelte":"{n} di {m} voci scelte","scaglioni":"Q a scaglioni sull'importo","metaPfte":"50% nel PFTE (appalto integrato)","metaEsecutivo":"50% nell'esecutivo","corsoOpera":"+20% in corso d'opera"},"incarico":{"titolo":"L'incarico","opzioni":[{"chiave":"appaltoIntegrato","nome":"Appalto integrato","aiuto":"Progettazione ed esecuzione affidate insieme: il computo passa al PFTE e quattro voci dell'esecutivo si dividono a metà."},{"chiave":"bim","nome":"Progetto in BIM obbligatorio","aiuto":"+10% sugli onorari, prima delle spese (allegato I.13, art. 2 c. 5)."},{"chiave":"collaudoInCorsoOpera","nome":"Collaudo in corso d'opera","aiuto":"+20% sul collaudo tecnico-amministrativo QdI.01."},{"chiave":"pCostante","nome":"P costante nelle voci a scaglioni","aiuto":"Usa il P dell'importo intero invece di ricalcolarlo fascia per fascia."}]},"studio":{"titolo":"Il tuo studio","ribasso":"Ribasso concordato con il cliente","ribassoAiuto":"Negli incarichi pubblici: sotto i 140.000 € la progettazione si può ridurre al massimo del 20%; da 140.000 € in su il ribasso in gara vale solo sul 35% del compenso.","spese":"Spese e oneri accessori","speseAiuto":"Forfettarie, al massimo il {max}% per quest'opera (art. 5). Proposte al massimo: puoi metterne meno.","giornata":"Quanto costa al tuo studio una giornata di lavoro","giornataAiuto":"Se non lo sai, 320 € è una media per uno studio piccolo. Clepsi lo calcola per ogni persona.","calcolaGiornata":"Non lo sai? Calcolalo in un minuto"},"risultato":{"titolo":"La tua parcella","compenso":"Compenso (CP)","bim":"Progetto in BIM (+10%)","spese":"Spese e oneri accessori ({p}%)","ribasso":"Ribasso ({p}%)","totale":"Compenso, IVA e cassa escluse","paga":"Con {euro} a giornata, questa parcella paga","giornata":"{n} giornata","giornate":"{n} giornate","eMezza":"e mezza","mezza":"Mezza giornata","resto":"di lavoro di studio. Il resto è margine.","sceglile":"Scegli almeno una prestazione","importoVuoto":"Scrivi l'importo dei lavori","barra":"Totale","vedi":"Vedi la parcella"},"pdf":{"apri":"Aprila in Clepsi","apertura":"Preparo la commessa…","paga":"Questa parcella ti paga {giornate}. Clepsi ti dice ogni sera quante ne hai già usate.","erroreApri":"Non siamo riusciti ad aprirla in Clepsi. Riprova tra un momento.","pulsante":"Scarica il riepilogo (PDF)","email":"La tua email","segnaposto":"studio@esempio.it","spiegazione":"Il riepilogo si scarica subito e te ne mandiamo una copia, con il link per aprirla in Clepsi: lì trovi il PDF completo, voce per voce. Usiamo la tua email solo per questo e, se spunti la casella, per un solo promemoria.","informativa":"Informativa privacy","scarica":"Scarica il riepilogo","invio":"Preparo il PDF…","annulla":"Annulla","fatto":"Fatto. Il riepilogo è scaricato.","fattoTesto":"Ti abbiamo mandato una copia per email, con il link per aprirla in Clepsi come prima commessa: dentro trovi il PDF completo, voce per voce.","errore":"Non siamo riusciti a preparare il PDF. Riprova tra un momento.","emailNonValida":"Questa email non sembra giusta.","troppi":"Hai provato tante volte di seguito. Riprova tra un'ora.","avvertenza":"Calcolo indicativo, basato sul D.M. 17 giugno 2016 e sui dati che hai inserito. Non è una consulenza: prima di usarla con un cliente o in una gara, verifica importi, categorie e parametri. La parcella resta sotto la responsabilità del professionista che la presenta; Clepsi non risponde di errori o di un uso diverso.","promemoria":"Tra 3 giorni mandami quante giornate vale questa parcella e come tenerle d'occhio (una sola email)."},"come":{"titolo":"Come si calcola","p1":"Per la progettazione vale l'allegato I.13 del Codice dei contratti (D.Lgs. 36/2023, aggiornato dal correttivo D.Lgs. 209/2024); per direzione lavori, sicurezza e collaudi il D.M. 17 giugno 2016. Entrambi calcolano il compenso di ogni prestazione come prodotto di quattro numeri:","formula":"CP = V × G × Q × P","v":"è il costo delle opere di ogni categoria, cioè l'importo dei lavori.","g":"è il grado di complessità dell'opera (tavola Z-1).","q":"è la specificità di ogni prestazione (tavola Z-2). Alcune voci hanno Q a scaglioni: si calcolano fascia per fascia.","p":"è il parametro base: 0,03 + 10 / V elevato a 0,4. Più l'opera è grande, più scende. Sotto i 25.000 € resta fermo al valore di 25.000 €.","p2":"Dal 2023 i livelli di progetto sono due. Il progetto di fattibilità tecnico-economica raccoglie le voci del vecchio preliminare e del definitivo; il computo metrico passa all'esecutivo. Nell'appalto integrato alcune voci dell'esecutivo si dividono a metà tra i due livelli. Se il BIM è obbligatorio, gli onorari crescono del 10%.","p3":"Alla somma si aggiungono le spese e gli oneri accessori, forfettari: fino al 25% per opere fino a un milione di euro, poi a scalare fino al 10% oltre i 25 milioni.","regole":"Come facciamo i conti: P con tutti i decimali (i bandi spesso lo arrotondano alla quarta cifra in percentuale, con differenze di pochi centesimi); nelle voci a scaglioni P si ricalcola sull'ampiezza di ogni fascia. Per la contabilità a misura (QcI.09) oltre i 500.000 € usiamo Q = 0,120 per edilizia e strutture: la Gazzetta stampa 0,012, quasi certamente un refuso (a corpo, QcI.10, il valore raddoppia).","fonti":"Fonti: D.M. Giustizia 17 giugno 2016 (G.U. n. 174 del 27 luglio 2016), tavole Z-1 e Z-2; D.Lgs. 36/2023, allegato I.13, come modificato dal D.Lgs. 209/2024."},"perche":{"titolo":"Perché le giornate","p1":"La parcella dice quanto incassi. Non dice se ti basta. Dividendola per il costo di una giornata di studio sai, prima di firmare, quante giornate puoi spendere su quella commessa senza andare in perdita.","p2":"Clepsi poi le conta per te: ogni sera, due tap a testa, e il margine si aggiorna da solo.","avvertenza":"Calcolo indicativo, basato sul D.M. 17 giugno 2016 e sui dati che hai inserito. Non è una consulenza: prima di usarla con un cliente o in una gara, verifica importi, categorie e parametri. La parcella resta sotto la responsabilità del professionista che la presenta; Clepsi non risponde di errori o di un uso diverso. IVA e contributo previdenziale esclusi."},"immagineAlt":"Calcola la parcella: il calcolatore gratuito di Clepsi per architetti e ingegneri","domande":{"occhiello":"Domande","titolo":"Domande sulla parcella","elenco":[{"domanda":"Come si calcola la parcella di un architetto o di un ingegnere?","risposta":"Per ogni categoria dell'opera si parte dall'importo dei lavori (V). Lo si moltiplica per il grado di complessità (G), per il peso di ogni prestazione scelta (Q) e per un parametro base (P) che scende al crescere dell'importo: P = 0,03 + 10 / V^0,4 (sotto i 25.000 € di lavori resta quello di 25.000 €). La somma delle prestazioni dà il compenso; poi si aggiungono le spese e si toglie l'eventuale ribasso. Il calcolatore qui sopra fa tutto questo voce per voce."},{"domanda":"Le tariffe del D.M. 17 giugno 2016 sono obbligatorie?","risposta":"Negli incarichi pubblici sono il riferimento per calcolare l'importo da mettere a base di gara, secondo l'allegato I.13 del Codice dei contratti. Con un committente privato il compenso si pattuisce liberamente, ma va messo per iscritto in un preventivo, e il decreto resta il riferimento più usato per sapere quanto vale una prestazione."},{"domanda":"Cos'è l'equo compenso e quando si applica?","risposta":"La legge 49/2023 stabilisce che il compenso dei professionisti deve essere proporzionato al lavoro svolto e coerente con i parametri ministeriali. Si applica agli incarichi della pubblica amministrazione e dei committenti più grandi, come banche, assicurazioni e imprese oltre una certa soglia di dipendenti o di fatturato. Per i privati cittadini il compenso resta libero."},{"domanda":"Quanto si può ribassare la parcella?","risposta":"Negli incarichi pubblici, sotto i 140.000 € la progettazione si può ridurre al massimo del 20%. Da 140.000 € in su il ribasso in gara vale solo sul 35% del compenso: il resto è fisso. Con i privati il ribasso è un accordo tra te e il cliente. Il calcolatore applica il ribasso che scrivi, sul compenso e sulle spese, senza controllare questi limiti, e ti mostra subito quante giornate ti costa."},{"domanda":"Quanto pesano le spese sulla parcella?","risposta":"Le spese e gli oneri accessori si calcolano in forma forfettaria sul compenso: al massimo il 25% per le opere fino a 1.000.000 € di lavori, poi la percentuale massima scende fino al 10% per le opere da 25.000.000 € in su. Il calcolatore propone il massimo consentito per la tua opera; puoi metterne meno."},{"domanda":"Il calcolatore è aggiornato?","risposta":"Sì: segue l'allegato I.13 del D.Lgs. 36/2023 come modificato dal correttivo D.Lgs. 209/2024, e il D.M. 17 giugno 2016 per direzione lavori, sicurezza e collaudi."}]}}`),cancella:{titolo:`Cancellati dagli aggiornamenti di Clepsi`,inCorso:`Un attimo, ti stiamo togliendo dagli aggiornamenti…`,fatto:`Fatto: la tua email non riceverà più aggiornamenti da Clepsi.`,giaFatto:`Questa email non riceve aggiornamenti: forse ti eri già cancellato.`,senzaCodice:`Il link non è completo. Apri di nuovo quello che trovi in fondo alla nostra email.`,errore:`Non siamo riusciti a cancellarti. Riprova tra un momento, o scrivi a info@clepsi.it.`,home:`Torna alla home`},privacy:{titolo:`Informativa privacy`,descrizione:`Come Clepsi usa i dati del calcolatore della parcella e della vecchia lista d'attesa.`,aggiornata:`Aggiornata il 31 ottobre 2026.`,intro:`Questa informativa riguarda il sito clepsi.it: il calcolatore della parcella, il calcolo del costo della giornata e la lista d'attesa, chiusa il 31 ottobre 2026. Diciamo cosa raccogliamo, perché, per quanto tempo e quali diritti hai (Regolamento UE 2016/679, articolo 13).`,perApp:`Per l'app Clepsi c'è un'informativa a parte:`,linkApp:`informativa per chi usa l'app`,sezioni:[{titolo:`Chi tratta i tuoi dati`,paragrafi:[`Titolare del trattamento: {nome}, partita IVA {partitaIva}.`,`Per qualsiasi domanda sui tuoi dati scrivi a {email}.`]},{titolo:`Quali dati raccogliamo`,paragrafi:[`Calcolatore, quando tocchi «Aprila in Clepsi»: i dati della parcella che hai calcolato (categorie e importi dell'opera, voci scelte, opzioni, ribasso, costo della giornata), senza email né altri dati su di te. La salviamo con un codice casuale, che sta solo nel link per aprirla nell'app.`,`Calcolatore, quando scarichi il riepilogo in PDF: la tua email e gli stessi dati della parcella; se spunti la casella del promemoria, anche questa scelta e il giorno in cui te lo mandiamo.`,`Se usi il calcolatore senza aprire la parcella in Clepsi e senza scaricare il PDF, o se calcoli il costo della giornata, non raccogliamo niente: i conti si fanno nel tuo browser.`,`Chi si è iscritto alla lista d'attesa prima del 31 ottobre 2026: la sua email, la pagina da cui si è iscritto, la lingua, la data e il testo sull'uso dell'email che aveva davanti.`,`Per proteggere il sito dagli abusi teniamo per 24 ore un'impronta cifrata del tuo indirizzo internet (non l'indirizzo): serve solo a limitare i tentativi ripetuti.`]},{titolo:`Perché e su quale base`,paragrafi:[`La parcella la salviamo perché tu possa aprirla in Clepsi come commessa; l'email del PDF ci serve per mandarti la copia con il link per aprirla. La base è la tua richiesta (art. 6.1.b): sei tu a toccare il pulsante. Il promemoria, uno solo, 3 giorni dopo, te lo mandiamo solo se spunti la casella: la base è il tuo consenso (art. 6.1.a). Puoi revocarlo prima scrivendo a info@clepsi.it; se apri la parcella in Clepsi prima, non parte.`,`L'email della lista d'attesa serve ad avvisarti che Clepsi si può provare. La base è il consenso che hai dato iscrivendoti (art. 6.1.a), che puoi revocare quando vuoi.`,`L'impronta dell'indirizzo internet serve alla sicurezza del sito: la base è il nostro legittimo interesse a evitare abusi (art. 6.1.f).`,`Non usiamo i tuoi dati per pubblicità, non li vendiamo e non li cediamo a nessuno.`]},{titolo:`Per quanto tempo`,paragrafi:[`Parcelle del calcolatore, con l'eventuale email: 90 giorni, poi le cancelliamo. Se nel frattempo la apri in Clepsi diventa una commessa del tuo studio: l'email si cancella e vale l'informativa per chi usa l'app.`,`Email della lista d'attesa: finché non ti cancelli e comunque non oltre il 31 ottobre 2027.`,`Impronta dell'indirizzo internet: 24 ore.`]},{titolo:`Chi li vede`,paragrafi:[`Solo il titolare. Per far funzionare il sito ci appoggiamo a fornitori che trattano i dati per nostro conto, come responsabili del trattamento: Supabase (database e funzioni del server, su server nell'Unione europea, a Francoforte), Resend (invio delle email, su server nell'Unione europea, in Irlanda) e GitHub (pubblicazione del sito, con GitHub Pages).`,`Alcuni di questi fornitori fanno parte di gruppi con sede fuori dall'Unione europea: gli eventuali trasferimenti sono coperti dalle garanzie previste dal Regolamento (decisione di adeguatezza UE-USA o clausole contrattuali standard).`]},{titolo:`I tuoi diritti`,paragrafi:[`Puoi chiedere di vedere i tuoi dati, correggerli, cancellarli, limitarne l'uso, riceverli in un formato leggibile o opporti al trattamento. Puoi revocare il consenso in ogni momento: in fondo alle email della lista d'attesa c'è il link per cancellarti, oppure scrivi a {email}.`,`Se pensi che i tuoi dati siano trattati in modo non corretto puoi rivolgerti al Garante per la protezione dei dati personali (garanteprivacy.it).`]}]},cookie:{titolo:`Informativa cookie`,descrizione:`Quali cookie usa il sito di Clepsi.`,aggiornata:`Aggiornata il 31 ottobre 2026.`,paragrafi:[`Il sito clepsi.it e l'app su app.clepsi.it non usano cookie di profilazione, né strumenti di statistica o di pubblicità. Per questo non ti chiediamo alcun consenso all'ingresso.`,`I caratteri e i video sono ospitati sul sito stesso: aprendo le pagine non contatti Google, YouTube o social network.`,`L'app tiene sul tuo telefono, nella memoria del browser, solo quello che le serve per funzionare: la sessione con cui sei entrato e una copia dei suoi file, per aprirsi in fretta. Sono strumenti tecnici: non servono a riconoscerti altrove e non li legge nessun altro.`,`Sito e app sono pubblicati con GitHub Pages, che non usa cookie. Come ogni servizio che pubblica siti, GitHub registra gli indirizzi internet delle visite per la sicurezza del servizio.`,`Per sapere come trattiamo i dati del calcolatore leggi l'informativa privacy; per l'app, l'informativa per chi usa l'app.`],privacy:`Informativa privacy`,privacyApp:`Informativa per chi usa l'app`},costo:{titoloPagina:`Quanto costa una giornata del tuo studio · Calcolo costo studio professionale · Clepsi`,descrizionePagina:`Altro che costo orario: quanto costa davvero una giornata del tuo studio di architettura o ingegneria? Calcolala per ogni persona, con stipendi, collaboratori e spese fisse. Gratis.`,immagineAlt:`Quanto costa una giornata del tuo studio: il calcolatore gratuito di Clepsi`,occhiello:`Il costo dello studio · Gratis, senza registrarti`,titolo:`Quanto costa davvero una giornata del tuo studio.`,titoloEvidenza:`davvero`,intro:`Per sapere se una commessa guadagna, devi sapere quanto ti costa ogni giornata di chi ci lavora. Non solo lo stipendio: anche l'affitto, i software, il commercialista. Inseriscili qui, persona per persona.`,orarioForte:`Cercavi il costo orario?`,orario:`In uno studio le ore non le ricorda nessuno, le giornate sì. Per questo qui si ragiona così.`,persone:{titolo:`Le persone dello studio`,aiuto:`Una riga per ogni persona che lavora sulle commesse. Anche tu.`,nome:`Nome o ruolo`,tipo:`Tipo`,tipi:{employee:`Dipendente`,freelance:`Collaboratore a partita IVA`,partner:`Titolare o socio`},importo:{employee:`Stipendio lordo annuo (RAL)`,freelance:`Compenso annuo allo studio`,partner:`Quanto vuoi guadagnare in un anno`},giornate:`Giornate in un anno`,aggiungi:`+ Aggiungi una persona`,togli:`Togli {nome}`,senzaNome:`Persona {n}`,esempio:[`Titolare`,`Dipendente`,`Collaboratrice`]},spese:{titolo:`Le spese dello studio`,spese:`Spese dello studio in un anno`,speseAiuto:`Affitto, utenze, software e licenze, assicurazione, commercialista, auto, formazione. Si dividono sulle giornate di tutti.`,coefficiente:`Quanto costa un dipendente allo studio, rispetto alla RAL`,coefficienteAiuto:`1,38 vuol dire che per 30.000 € di RAL lo studio ne spende 41.400: contributi, TFR e INAIL. È una stima: chiedi il dato esatto al tuo consulente.`,giornateAiuto:`210 giornate sono un anno pieno: 365 giorni meno weekend, festivi, ferie e qualche giorno di malattia. Per un part-time mettine meno.`},risultato:{titolo:`Il costo del tuo studio`,persona:`Persona`,giornata:`Giornata`,mezza:`Mezza giornata`,medio:`Una giornata del tuo studio costa in media`,sotto:`Ogni commessa che ti paga meno di {costo} a giornata, ti costa.`,vuoto:`Scrivi quanto costa almeno una persona.`,privacy:`Tutto si calcola qui, nel tuo browser. Non salviamo niente.`},commessa:{domanda:`Quanto ti paga la tua prossima commessa?`,copre:`Copre {giornate} del tuo studio.`,poi:`Quante ne userà davvero? Lo scopri solo contandole. Ogni sera il tuo team indica con due tap dove ha lavorato, e Clepsi ti dice se bastano. Mentre la commessa è aperta.`,entra:`Prova l'app`,giornata:`1 giornata`,giornate:`{n} giornate`,eMezza:`e mezza`,mezza:`mezza giornata`},perche:{occhiello:`Il conto giusto`,titolo:`Perché una giornata non costa lo stipendio diviso 365.`,testo:`Uno stipendio da 30.000 € non costa 30.000 €: con contributi e TFR, allo studio ne costa circa 41.400. Poi ci sono le spese che non appartengono a nessuna commessa ma le pagano tutte. E un anno non ha 365 giornate di lavoro: tolti weekend, festivi, ferie e malattia, ne restano circa 210. Se dividi per 365, il tuo costo sembra quasi la metà di quello che è, e ogni preventivo nasce già in perdita.`,stipendio:`Lo stipendio`,costoStudio:`Quanto costa allo studio`,spese:`La sua parte delle spese`,giornate:`Giornate in un anno`,giornata:`Una sua giornata`,esempioNota:`Esempio con 18.000 € di spese in tre persone.`},domande:{occhiello:`Domande`,titolo:`Domande sul costo dello studio`,elenco:[{domanda:`E il costo orario?`,risposta:`Puoi ottenerlo dividendo per le ore di una giornata, ma in uno studio è un numero che serve poco. Nessuno ricorda se su un progetto ha passato tre ore o tre ore e venti; tutti sanno dove hanno lavorato la mattina e il pomeriggio. Le giornate si contano senza timer e senza timesheet, ed è con quelle che si capisce se una commessa guadagna.`},{domanda:`Quanto costa in media una giornata di uno studio di architettura?`,risposta:`Dipende da quante persone ci sono e da quanto costano gli spazi, ma per uno studio piccolo spesso è intorno ai 300 €. L'unico numero che conta è il tuo: calcolalo qui sopra.`},{domanda:`Devo contare anche le mie giornate da titolare?`,risposta:`Sì. Se il tuo compenso non entra nel costo, ogni commessa sembra guadagnare più di quanto guadagna davvero, e il tuo lavoro diventa gratis.`},{domanda:`Perché 210 giornate?`,risposta:`Perché un anno di lavoro non ha 365 giorni: tolti weekend, festivi, ferie e qualche giorno di malattia, ne restano circa 210. È lo stesso numero da cui parte Clepsi. Se nel tuo studio sono diverse, o una persona lavora part-time, cambiale persona per persona.`}]},chiusura:`Il costo di una giornata è il primo numero. Il secondo è quante giornate si prende ogni commessa. Clepsi li mette insieme ogni sera, con due tap del tuo team, e ti dice come chiuderà ogni commessa.`},gestionale:{titoloPagina:`Gestionale per studi di architettura e ingegneria: il margine di ogni commessa · Clepsi`,descrizionePagina:`Clepsi è il gestionale delle commesse per studi di architettura e ingegneria: budget in giornate, margine previsto e varianti, senza timer né timesheet. Ogni sera due tap.`,occhiello:`Gestionale per studi di architettura e ingegneria`,titolo:`Un gestionale che non ti chiede di segnare le ore.`,titoloEvidenza:`non ti chiede`,intro:`Clepsi parte dalla domanda che conta: questa commessa sta guadagnando? Ogni sera il tuo team indica con due tap dove ha lavorato. Il resto lo fa Clepsi.`,entra:`Prova l'app`,metaPrezzo:`Gratis, senza carta. I primi 100 studi pagano la metà il primo anno.`,problema:{occhiello:`Gli altri gestionali`,titolo:`Partono tutti dal timesheet. E finiscono tutti allo stesso modo.`,scene:[{frase:`Ognuno segna le ore.`,conto:`A memoria, il venerdì.`,nota:`Nessuno ricorda se su un progetto ha passato tre ore o tre ore e venti.`},{frase:`Qualcuno le controlla.`,conto:`E il team si sente cronometrato.`,nota:`Chi disegna non timbra il cartellino.`},{frase:`Quasi nessuno le guarda.`,conto:`Il margine resta una sensazione.`,nota:`Lo scopri a commessa chiusa, quando non puoi più rimediare.`}]},sera:{occhiello:`Ogni sera`,titolo:`La gestione delle commesse, senza timesheet.`,testo:`Mezza giornata è l'unità giusta per uno studio: nessuno ricorda se su un progetto ha passato tre ore o tre ore e venti, ma tutti sanno dove hanno lavorato la mattina e il pomeriggio. Alle 19 arriva la domanda, due tap, fatto. Se qualcuno si dimentica, un promemoria.`},budget:{occhiello:`Il budget`,titolo:`Il budget di ogni commessa, in giornate.`,testo:`Il compenso della commessa diventa giornate, fase per fase, in base al costo di chi ci lavora. Sai quante ne restano prima di andare in perdita e quale fase ha già superato il budget, mentre la commessa è ancora aperta.`,commessa:`SBR · Scuola Brera`,fasi:[{nome:`Fattibilità tecnico-economica`,stato:`done`,usate:6,budget:6},{nome:`Progetto esecutivo`,stato:`almost`,usate:12,budget:10},{nome:`Esecuzione dei lavori`,stato:`started`,usate:2,budget:9}],stati:{todo:`Da fare`,started:`Iniziata`,half:`A metà`,almost:`In chiusura`,done:`Fatta`},diBudget:`{usate} di {budget}`,usata:`usata`,oltreBudget:`oltre budget`,libera:`libera`,fraseForte:`Il compenso copre ancora 5 giornate.`,frase:`Margine previsto 11%.`,etichettaFase:`{nome}: {stato}, {usate} giornate usate su {budget} di budget`},previsione:{occhiello:`La previsione`,titolo:`Il margine previsto, ogni mattina.`,testo:`Ogni sera le giornate di tutti, ogni venerdì l'avanzamento delle fasi. Clepsi li confronta con il compenso e ti dice come chiuderà ogni commessa: in attivo, con margine stretto o in perdita. Il margine di commessa non lo scopri a fine lavoro: lo vedi quando c'è ancora tempo per rimediare.`,punti:[{titolo:`In attivo, margine stretto, in perdita.`,testo:`Ogni commessa ha il suo stato, scritto in parole e non solo a colori.`},{titolo:`Le giornate che restano.`,testo:`Quante giornate copre ancora il compenso, prima che la commessa vada in perdita.`},{titolo:`Previsione ferma.`,testo:`Se il venerdì nessuno aggiorna le fasi, il lunedì la commessa te lo segnala: non ti fidi di un numero vecchio.`}]},varianti:{occhiello:`Le varianti`,titolo:`Le varianti che il cliente deve pagare.`,testo:`Il lavoro in più chiesto dal cliente, segnato dal team, non si perde: Clepsi lo mette da parte e gli dà un valore. A fine commessa il riepilogo per il cliente è pronto.`,commessa:`VRO · Villa Rossi · varianti`,voci:[{nome:`Seconda proposta per la cucina`,giornate:`2 giornate`,valore:`640 €`},{nome:`Spostamento del bagno al primo piano`,giornate:`Mezza giornata`,valore:`160 €`},{nome:`Nuovo render della facciata`,giornate:`1 giornata`,valore:`320 €`}],totale:`Da proporre al cliente`,totaleValore:`1.120 €`},bilancio:{occhiello:`Il bilancio`,titolo:`Il bilancio, per il prossimo preventivo.`,testo:`Quando chiudi una commessa sai quanto ti ha reso ogni giornata, rispetto a quanto ti costa e alle commesse dello stesso tipo. Il prossimo preventivo non lo fai a sensazione.`},domande:{occhiello:`Domande`,titolo:`Quello che ci chiedono gli studi`,elenco:[{domanda:`Clepsi è un software per controllare i dipendenti?`,risposta:`No. Niente timer, niente ore, niente posizione: ognuno indica solo su quale commessa ha lavorato la mattina e su quale il pomeriggio. I collaboratori vedono le proprie giornate, non i compensi né i costi. Il costo di ogni persona lo vede solo chi amministra lo studio.`},{domanda:`Sostituisce il programma per le fatture?`,risposta:`No. Clepsi si occupa del margine delle commesse, non della contabilità: continui a fatturare come fai oggi.`},{domanda:`Va bene anche per uno studio di ingegneria?`,risposta:`Sì: commesse, fasi e giornate funzionano allo stesso modo per architetti e ingegneri. Puoi partire anche da una parcella calcolata con il nostro calcolatore: le fasi che scegli diventano le fasi della commessa.`},{domanda:`Posso provarla adesso?`,risposta:`Sì. Funziona già, e ogni settimana la miglioriamo con gli studi che la usano. È gratis e non serve la carta. Le app per iPhone e Android arrivano sugli store più avanti; intanto si installa dal browser in un minuto.`}]}},installa:{reel:{occhiello:`In due minuti`,titolo:`Lo studio pronto in tre passi.`,testo:`Il nome dello studio e quante persone siete, la prima commessa con il suo compenso, il link per il team. Niente da configurare: stasera alle 19 arriva la prima domanda.`},titoloPagina:`Prova l'app Clepsi · beta gratuita per studi di architettura e ingegneria`,descrizionePagina:`Prova Clepsi gratis, senza carta. Si installa dal browser su iPhone e Android in un minuto.`,cartolina:`Hai ricevuto la nostra cartolina: ecco come provarla.`,occhiello:`Gratis · Senza carta · Un minuto`,titolo:`Un minuto adesso.`,titoloEvidenza:`Stasera la prima domanda.`,riga:`Tra una settimana sai come chiuderà ogni commessa.`,sottotitolo:`Crei lo studio, inserisci una commessa, rispondi dal telefono con due tap la sera. Niente timer, niente timesheet.`,avvio:{computer:[{titolo:`Crea lo studio qui.`,testo:`Clepsi si apre nel browser: crei lo studio e la prima commessa, segui le commesse e vedi la previsione.`},{titolo:`Installala sul telefono.`,testo:`È lì che arriva la domanda delle 19. Inquadra il codice con la fotocamera.`}],telefono:[{titolo:`Apri l'app.`,testo:`Su iPhone da Safari, su Android da Chrome.`},{titolo:`Aggiungila alla schermata Home.`,testo:`Così alle 19 ti arriva la domanda, come una notifica.`}],come:`Guarda come si fa`},invito:{occhiello:`Un invito dal tuo studio`,titolo:`Ti hanno invitato`,titoloEvidenza:`su Clepsi.`,riga:`Stasera alle 19 la prima domanda.`,sottotitolo:`Dove hai lavorato, mattina e pomeriggio: due tap. Niente timer, niente importi.`},adesso:{titolo:`Cosa succede adesso.`,passi:[{titolo:`Adesso, due minuti.`,testo:`Crei lo studio e la prima commessa, dal computer o dal telefono, anche partendo da una parcella calcolata sul sito.`},{titolo:`Stasera alle 19.`,testo:`Arriva la domanda: dove hai lavorato, mattina e pomeriggio. Due tap.`},{titolo:`Tra una settimana.`,testo:`Vedi dove sono andate le giornate e come chiuderà la commessa, anche dal computer.`}],riga:`Puoi iniziare da solo e invitare il team quando ti ha convinto.`},ricevere:{occhiello:`Come si installa`,titolo:`Per ricevere la domanda delle 19 sul telefono.`,beta:`Clepsi è in beta e non è ancora sugli store di Apple e Google: per ora si installa dal browser, in un minuto.`,computerTitolo:`Anche dal computer.`,computerTesto:`Chi amministra lo studio o segue una commessa può usare Clepsi dal browser, su app.clepsi.it. Sul telefono arriva la domanda della sera.`},fiducia:{occhiello:`Perché fidarti`,punti:[`Nata in uno studio di architettura, usata ogni sera.`,`I collaboratori indicano solo la commessa: nessun timer, e non vedono mai un importo.`,`I primi 100 studi pagano la metà il primo anno.`]},apri:`Apri l'app`,indirizzo:`app.clepsi.it`,instagram:{domanda:`Arrivi da Instagram?`,iphone:{breve:`Riaprila in Safari.`,spiegazione:`Il browser di Instagram non installa app. Tocca ⋯ in alto a destra, scegli «Apri nel browser» e segui i passaggi da Safari.`},android:{breve:`Riaprila in Chrome.`,spiegazione:`Il browser di Instagram non installa app. Tocca ⋮ in alto a destra, scegli «Apri in Chrome» e segui i passaggi da Chrome.`}},telefono:`Che telefono hai?`,iphone:`iPhone`,android:`Android`,passaggio:`Passaggio {n} di 4 · {telefono}`,telefonoIphone:`iPhone, Safari`,telefonoAndroid:`Android, Chrome`,passaggi:{iphone:[{titolo:`Apri l'app in Safari`,testo:`Tocca «Apri l'app» qui sopra, da Safari. Su iPhone l'installazione funziona solo da Safari.`},{titolo:`Tocca Condividi`,testo:`È il quadrato con la freccia verso l'alto, nella barra in basso.`},{titolo:`Aggiungi alla schermata Home`,testo:`Scorri l'elenco, tocca «Aggiungi alla schermata Home» e poi «Aggiungi» in alto a destra.`},{titolo:`Apri Clepsi e consenti le notifiche`,testo:`Apri l'icona dalla Home, entra nel tuo studio e tocca «Consenti». Alle 19 arriva la domanda.`}],android:[{titolo:`Apri l'app in Chrome`,testo:`Tocca «Apri l'app» qui sopra, da Chrome.`},{titolo:`Tocca i tre puntini`,testo:`Sono in alto a destra, accanto all'indirizzo.`},{titolo:`Installa l'app`,testo:`Tocca «Installa app» (o «Aggiungi a schermata Home») e poi «Installa».`},{titolo:`Apri Clepsi e consenti le notifiche`,testo:`Apri l'icona dalla schermata Home, entra nel tuo studio e tocca «Consenti». Alle 19 arriva la domanda.`}]},nota:{iphone:`Per le notifiche serve iOS 16.4 o successivo. Se il tuo iPhone è più vecchio, Clepsi ti manda la domanda delle 19 per email.`,android:`Se non vedi «Installa app», aggiorna Chrome dal Play Store. Senza notifiche, Clepsi ti manda la domanda delle 19 per email.`},schermo:{titolo:`Ogni sera due tap.`,testo:`Crea il tuo studio e invita il team.`,inizia:`Inizia`,copia:`Copia`,preferiti:`Aggiungi ai preferiti`,home:`Aggiungi alla schermata Home`,stampa:`Stampa`,nuovaScheda:`Nuova scheda`,cronologia:`Cronologia`,preferitiAndroid:`Preferiti`,installa:`Installa app`,impostazioni:`Impostazioni`,notificaTitolo:`Com'è andata oggi?`,notificaTesto:`Mattina e pomeriggio, due tap.`,ora:`19:00`},altri:{occhiello:`Il tuo studio`,titolo:`Poi tocca agli altri. Un minuto a testa.`,testo:`Quando inviti qualcuno dello studio gli arriva un link che apre questa pagina: stessi passaggi, sul suo telefono. Da quella sera la domanda delle 19 arriva anche a lui.`,copia:`Copia il link di questa pagina`,copiato:`Link copiato`,nota:`Da mandare su WhatsApp o per email.`},domande:{occhiello:`Domande`,titolo:`Sulla beta.`,elenco:[{domanda:`Perché non è sull'App Store o su Google Play?`,risposta:`Ci arriverà. Nella beta la miglioriamo ogni settimana con gli studi che la usano, e dal browser gli aggiornamenti arrivano subito, senza scaricare niente.`},{domanda:`Le notifiche arrivano davvero?`,risposta:`Sì, se le consenti al primo accesso. Su iPhone servono iOS 16.4 o successivo e Clepsi aperta dall'icona sulla schermata Home.`},{domanda:`Quando Clepsi arriverà sugli store, perdo i miei dati?`,risposta:`No: scarichi l'app, entri con lo stesso account e ritrovi tutto.`},{domanda:`Quanto costa?`,risposta:`Adesso è gratis, senza carta. Quando arriveranno gli abbonamenti, i primi 100 studi pagano la metà il primo anno.`,soloTitolare:!0},{domanda:`Qualcosa non funziona?`,risposta:`Scrivici a info@clepsi.it. È proprio quello che ci serve dalla beta.`}]},qr:{etichetta:`Codice QR per aprire questa pagina sul telefono`}},privacyApp:{titolo:`Informativa per chi usa l'app`,descrizione:`Cosa registra l'app Clepsi, cosa non registra e chi vede cosa: per chi amministra lo studio e per chi ci lavora.`,aggiornata:`Aggiornata il 31 ottobre 2026.`,intro:`Clepsi serve a uno studio di architettura o di ingegneria per sapere quanto guadagna su ogni commessa. Qui diciamo, in parole semplici, cosa registra, cosa non registra mai e chi vede cosa (Regolamento UE 2016/679, articoli 13 e 28).`,collaboratoriTitolo:`Se lavori in uno studio che usa Clepsi`,collaboratori:[`Clepsi non è un controllo delle presenze. Ogni sera ti chiede solo dove hai lavorato la mattina e dove il pomeriggio: su quale commessa, in attività di studio, oppure se eri assente. Niente di più.`,`Clepsi non registra mai: le ore, gli orari di entrata e di uscita, dove ti trovi, cosa fai sul telefono, le altre app, i contatti, le foto, il microfono o la fotocamera. Non c'è nessun timer.`,`Tu vedi le tue mezze giornate. Non vedi importi, compensi, costi né margini, nemmeno tradotti in giornate.`,`Chi è responsabile di una commessa vede le giornate e il margine delle sue commesse, ma non quanto costa ciascuna persona.`,`Il costo di ogni persona lo vede solo chi amministra lo studio.`,`Le tue risposte le puoi correggere per la settimana in corso. Puoi spegnere la domanda della sera, o cambiarne l'orario, dal tuo profilo.`],sezioni:[{titolo:`Chi tratta i dati`,paragrafi:[`I dati del lavoro dello studio (persone, commesse, fasi, mezze giornate, costi, spese) appartengono allo studio che usa Clepsi, che ne è il titolare. Clepsi li tratta per conto dello studio, come responsabile del trattamento, solo per far funzionare l'app.`,`Per il tuo account (l'email con cui entri) e per le email che ti mandiamo, il titolare è Clepsi: {nome}, partita IVA {partitaIva}, {email}.`]},{titolo:`Cosa registra l'app`,paragrafi:[`Di ogni persona: nome, email, ruolo nello studio, giorni di lavoro e, se li usa, l'orario della domanda della sera e i suoni dell'app.`,`Ogni giorno di lavoro: dove la persona ha lavorato la mattina e dove il pomeriggio (commessa e fase, attività di studio o assenza) e chi ha fatto l'ultima modifica.`,`Per chi amministra lo studio: il costo annuo di ogni persona, i compensi delle commesse e le spese, che servono a calcolare il margine.`,`Per mandare le notifiche: un codice del telefono, che non dice chi sei né dove sei.`]},{titolo:`Notifiche ed email`,paragrafi:[`Alle 19 arriva la domanda della sera, poi un promemoria se non hai risposto, e il venerdì una domanda sulle commesse a chi ne è responsabile. Se non hai attivato le notifiche su nessun telefono, la domanda delle 19 arriva per email.`,`Le notifiche passano dai servizi di Apple e di Google, che le recapitano al telefono senza poterne leggere il contenuto.`]},{titolo:`Lo studio di esempio`,paragrafi:[`Chi guarda lo studio di esempio entra senza email, con un utente anonimo. I dati sono inventati, non si salva niente e tutto si cancella dopo due giorni.`]},{titolo:`Dove stanno e per quanto`,paragrafi:[`I dati stanno su server nell'Unione europea: Supabase a Francoforte (database e funzioni del server) e Resend in Irlanda (email). L'app è pubblicata con GitHub Pages. Alcuni di questi fornitori fanno parte di gruppi con sede fuori dall'Unione europea: gli eventuali trasferimenti sono coperti dalle garanzie previste dal Regolamento.`,`Restano finché lo studio usa Clepsi. Quando lo studio ce lo chiede, li cancelliamo entro 30 giorni.`,`Non guardiamo i dati degli studi, se non quando lo studio ci chiede aiuto o per la sicurezza del servizio. Non li usiamo per pubblicità, non li vendiamo e non li cediamo a nessuno.`]},{titolo:`I tuoi diritti`,paragrafi:[`Puoi chiedere di vedere i tuoi dati, correggerli, cancellarli, limitarne l'uso o riceverli in un formato leggibile: per i dati del lavoro rivolgiti al tuo studio, per il tuo account scrivi a {email}. Se ti rivolgi a noi per i dati dello studio, giriamo la richiesta allo studio.`,`Se pensi che i tuoi dati siano trattati in modo non corretto puoi rivolgerti al Garante per la protezione dei dati personali (garanteprivacy.it).`]}]},funzioni:JSON.parse(`{"reel":{"previsione":{"file":"reel-previsione","secondi":19,"nome":"Clepsi: come chiuderà ogni commessa","descrizione":"L'app nello studio di esempio: la Home con le commesse e il loro stato, poi Uffici Lambrate, in perdita, con il margine previsto, il lavoro fatto e le fasi oltre budget.","etichetta":"Video dell'app: la Home dello studio con le commesse e il loro stato, poi la commessa Uffici Lambrate in perdita con il margine previsto."},"giornate":{"file":"reel-parcella","secondi":39,"nome":"Clepsi: dalla parcella alla commessa","descrizione":"Si calcola la parcella su clepsi.it, le voci scelte diventano le fasi, si vede quante giornate paga il compenso e con un tocco la commessa è pronta nell'app.","etichetta":"Video dell'app: la parcella calcolata su clepsi.it diventa una commessa con le sue fasi e le giornate che il compenso paga."},"varianti":{"file":"reel-venerdi","secondi":27,"nome":"Clepsi: il venerdì, un minuto","descrizione":"Il venerdì alle 18 il responsabile aggiorna lo stato delle fasi e segna le varianti chieste dal cliente; le previsioni si aggiornano subito.","etichetta":"Video dell'app: la domanda del venerdì, con lo stato delle fasi e le varianti del cliente da far pagare."},"settimana":{"file":"reel-recupero","secondi":30,"nome":"Clepsi: niente buchi nella settimana","descrizione":"Alle 21 il promemoria per chi non ha risposto; si recupera la giornata di ieri, mattina e pomeriggio, e poi quella di oggi. La settimana resta completa.","etichetta":"Video dell'app: il promemoria delle 21 e il recupero della giornata di ieri, perché la settimana resti senza buchi."},"bilancio":{"file":"reel-chiusura","secondi":32,"nome":"Clepsi: la commessa chiusa","descrizione":"Con un tocco si chiude la commessa: il bilancio vero, le varianti pronte da fatturare e quanto rende una giornata per tipo di incarico.","etichetta":"Video dell'app: si chiude una commessa e compare il bilancio, con le varianti da fatturare e la resa per giornata."},"fatica":{"file":"reel-collaboratore","secondi":33,"nome":"Clepsi: il collaboratore, la prima sera","descrizione":"Il collaboratore entra con un link e la sua email, alle 19 gli arriva la domanda e risponde con due tap: mattina e pomeriggio.","etichetta":"Video dell'app: un collaboratore entra con un link, alle 19 arriva la domanda e risponde con due tap."},"parcella":{"file":"reel-parcella","secondi":39,"nome":"Clepsi: dalla parcella alla commessa","descrizione":"Si calcola la parcella su clepsi.it, le voci scelte diventano le fasi, si vede quante giornate paga il compenso e con un tocco la commessa è pronta nell'app.","etichetta":"Video dell'app: la parcella calcolata su clepsi.it diventa una commessa con le sue fasi e le giornate che il compenso paga."},"installa":{"file":"reel-tre-passi","secondi":39,"nome":"Clepsi: lo studio pronto in tre passi","descrizione":"Il nome dello studio e quante persone siete, la prima commessa con il suo compenso, il link per il team: stasera alle 19 arriva la prima domanda.","etichetta":"Video dell'app: lo studio pronto in tre passi, con la prima commessa e il link per invitare il team."}},"altre":{"occhiello":"Le altre funzioni","titolo":"Tutto quello che Clepsi fa per le tue commesse.","scopri":"Scopri"},"previsione":{"titoloPagina":"Margine di commessa previsto per studi di architettura · Clepsi","descrizionePagina":"Sai come chiuderà ogni commessa del tuo studio: in attivo, margine stretto o in perdita. Il margine previsto si aggiorna ogni sera, senza timesheet.","nome":"Previsione del margine","titolo":"Il margine di ogni commessa, prima della fine.","titoloEvidenza":"prima della fine.","intro":"Clepsi confronta il compenso con le giornate già lavorate e con l'avanzamento delle fasi, e ti dice come chiuderà ogni commessa del tuo studio di architettura o di ingegneria: in attivo, con margine stretto o in perdita. Lo sai mentre lavori, quando c'è ancora tempo per rimediare.","calcolo":{"occhiello":"Come funziona","titolo":"Come si calcola il margine previsto di una commessa.","testo":"Per ogni commessa Clepsi tiene tre numeri: il compenso, i costi e il margine previsto. Nessuno deve segnare le ore: i costi arrivano dalle mezze giornate che il team indica ogni sera, l'avanzamento dalle fasi che il responsabile aggiorna una volta a settimana.","passi":[{"titolo":"Le giornate di tutti","testo":"Ogni sera, due tap: su quale commessa si è lavorato la mattina e su quale il pomeriggio. Ogni mezza giornata vale il costo di chi l'ha lavorata."},{"titolo":"A che punto è il lavoro","testo":"Il venerdì il responsabile dice, fase per fase, se è iniziata, a metà, quasi finita o fatta. Bastano pochi secondi."},{"titolo":"Come chiuderà","testo":"Clepsi confronta quanto hai speso con il lavoro fatto e proietta i costi fino alla fine. Il compenso meno i costi previsti è il margine previsto."}]},"stati":{"occhiello":"Lo stato di ogni commessa","titolo":"In attivo, margine stretto o in perdita.","testo":"Ogni commessa ha il suo stato, scritto in parole e non solo a colori. Lo vedi ogni mattina nella prima schermata, insieme alle giornate che il compenso copre ancora.","voci":[{"stato":"attivo","nome":"In attivo","testo":"Il margine previsto è almeno il 15% del compenso."},{"stato":"stretto","nome":"Margine stretto","testo":"Si chiude sopra zero, ma sotto il 15%: è il momento di guardarci."},{"stato":"perdita","nome":"In perdita","testo":"I costi previsti superano il compenso: se non cambia qualcosa, ci rimetti."},{"stato":"iniziata","nome":"Appena iniziata","testo":"Ancora pochi dati: Clepsi aspetta prima di darti un numero che non regge."}],"ferma":"Se il venerdì nessuno aggiorna le fasi, il lunedì la commessa compare come «previsione ferma»: non decidi su un numero vecchio."},"ruoli":{"occhiello":"Chi vede cosa","titolo":"Chi vede il margine delle commesse.","testo":"Il margine è un dato delicato. In Clepsi ognuno vede solo quello che gli serve, e le regole valgono nel database, non solo nelle schermate.","voci":[{"chi":"Titolare e amministratori","testo":"Il margine di tutte le commesse e il costo di ogni persona."},{"chi":"Capo commessa","testo":"Il margine previsto delle sue commesse, mai il costo dei colleghi."},{"chi":"Collaboratori","testo":"Solo le proprie mezze giornate: nessun importo, nessun margine."}]},"domande":{"occhiello":"Domande","titolo":"Domande sul margine di commessa.","elenco":[{"domanda":"Serve segnare le ore per avere il margine previsto?","risposta":"No. Bastano le mezze giornate: ogni sera mattina e pomeriggio, due tap. Il costo di ogni mezza giornata lo calcola Clepsi dal costo di chi l'ha lavorata, che vede solo chi amministra lo studio."},{"domanda":"Da quando vedo la previsione di una commessa?","risposta":"Appena c'è almeno il 5% di lavoro fatto e qualche mezza giornata segnata. Prima la commessa compare come «Appena iniziata», così non ti fidi di un numero costruito su pochi dati."},{"domanda":"Quanto è precisa la previsione?","risposta":"Tanto quanto è aggiornato l'avanzamento delle fasi. Per questo Clepsi lo chiede una volta a settimana e, se nessuno risponde, segna la previsione come ferma invece di mostrarti un numero vecchio."},{"domanda":"Le varianti cambiano il margine?","risposta":"No. Le varianti sono giornate già lavorate che Clepsi mette da parte con il loro valore, per il riepilogo da presentare al cliente. Se il cliente le paga e il compenso cresce, aggiorni il compenso e la previsione si ricalcola."}]}},"giornate":{"titoloPagina":"Budget di commessa in giornate, fase per fase · Clepsi","descrizionePagina":"Clepsi trasforma il compenso di ogni commessa in giornate di lavoro, fase per fase. Sai quante ne restano e quale fase ha già superato il budget.","nome":"Budget in giornate","titolo":"Il compenso diventa giornate, fase per fase.","titoloEvidenza":"fase per fase.","intro":"Un compenso di 18.000 € non dice quanto lavoro puoi metterci. Clepsi lo traduce in giornate per ogni fase della commessa, in base al costo del tuo studio. Così sai quante giornate restano e quale fase le sta finendo prima del previsto.","calcolo":{"occhiello":"Come funziona","titolo":"Come si calcola il budget in giornate di una commessa.","testo":"Il budget nasce dal compenso, non da una stima a occhio. Clepsi toglie il margine che vuoi tenere e divide quello che resta per il costo medio di una giornata del tuo studio.","passi":[{"titolo":"Il compenso di ogni fase","testo":"Scrivi il compenso fase per fase. Se hai solo il totale, Clepsi lo divide tra le fasi e tu lo correggi dove serve."},{"titolo":"Tolto il margine che vuoi","testo":"Di partenza il 25%, e lo cambi commessa per commessa: un incarico per un ente pubblico non è una villa privata."},{"titolo":"Diviso il costo di una giornata","testo":"Il costo medio di una giornata del tuo studio. Il risultato è il budget della fase, arrotondato alla mezza giornata."}]},"fasi":{"occhiello":"Le fasi","titolo":"Ogni fase della commessa, a colpo d'occhio.","testo":"Nella scheda della commessa ogni fase ha i suoi quadratini, uno per giornata. Si riempiono con le mezze giornate che il team segna ogni sera, e il venerdì il responsabile dice a che punto è il lavoro.","punti":[{"titolo":"Le giornate usate.","testo":"In nero, man mano che il team lavora sulla fase."},{"titolo":"Oltre il budget.","testo":"In rosso quando le giornate usate superano quelle previste: lo vedi mentre succede."},{"titolo":"Le giornate che restano.","testo":"In chiaro, quelle ancora libere prima di finire il budget della fase."}]},"contrario":{"occhiello":"Al contrario","titolo":"Sai già quante giornate servono? Il compenso lo calcola Clepsi.","testo":"Con «Scrivo le giornate» fai il calcolo al contrario: indichi le giornate che ti servono per ogni fase e Clepsi ti dice quale compenso chiedere per tenere il margine che vuoi, arrotondato a 100 €. Per partire dalla parcella, c'è il calcolatore gratuito.","link":"Calcola la parcella","passi":[{"titolo":"Progetto definitivo: 12 giornate","testo":"Le giornate che pensi di metterci, in base all'esperienza."},{"titolo":"Con un margine del 25%","testo":"Quello che vuoi tenere per lo studio, oltre ai costi."},{"titolo":"Compenso da chiedere: 5.100 €","testo":"Con una giornata dello studio a 320 €, arrotondato a 100 €."}]},"domande":{"occhiello":"Domande","titolo":"Domande sul budget di commessa.","elenco":[{"domanda":"Come si calcolano le giornate di budget di una fase?","risposta":"Compenso della fase, meno il margine che vuoi tenere, diviso il costo medio di una giornata del tuo studio. Il budget si salva in euro e si mostra in giornate, arrotondato alla mezza giornata."},{"domanda":"Posso usare un margine diverso per ogni commessa?","risposta":"Sì. Di partenza è il 25%, ma lo cambi per ogni commessa: le giornate di budget si ricalcolano subito."},{"domanda":"E se ho solo il compenso totale?","risposta":"Scegli «Ho solo il totale»: Clepsi lo divide in parti uguali tra le fasi, arrotondando a 100 €, e mette il resto sull'ultima. Poi correggi dove serve."},{"domanda":"Cosa succede quando una fase supera il budget?","risposta":"I quadratini in più diventano rossi e la previsione del margine ne tiene conto. Clepsi non blocca niente: ti avvisa in tempo per decidere cosa fare."}]}},"varianti":{"titoloPagina":"Varianti di commessa: il lavoro in più da far pagare · Clepsi","descrizionePagina":"Le richieste in più del cliente non si perdono: Clepsi segna le varianti in mezze giornate, dà loro un valore e prepara il riepilogo per il cliente.","nome":"Varianti da far pagare","titolo":"Il lavoro in più, da far pagare.","titoloEvidenza":"da far pagare.","intro":"Una seconda proposta per la cucina, un render in più, il bagno spostato al primo piano. Nelle commesse dello studio il lavoro extra chiesto dal cliente si perde nelle settimane. Clepsi lo mette da parte, gli dà un valore e a fine commessa hai il conto pronto.","come":{"occhiello":"Come funziona","titolo":"Come si segnano le varianti di una commessa.","testo":"Nessuno deve decidere la sera se una giornata era una variante. Ci pensa chi segue la commessa, una volta a settimana, con quello che sa del cliente.","passi":[{"titolo":"Il team lavora come sempre","testo":"Ogni sera due tap: su quale commessa si è lavorato la mattina e su quale il pomeriggio."},{"titolo":"Il venerdì, il responsabile","testo":"Indica quante mezze giornate della settimana erano lavoro in più, e per cosa: «Seconda proposta per la cucina»."},{"titolo":"Clepsi dà un valore","testo":"Il costo di quelle mezze giornate, e le mette nel conto delle varianti da proporre al cliente."}]},"margine":{"occhiello":"Varianti e margine","titolo":"Le varianti sono un conto a parte.","testo":"Le varianti non aggiungono tempo e non spostano la previsione: sono giornate già lavorate e già contate nei costi. Servono a sapere quanto lavoro hai regalato e a chiederlo al cliente prima di chiudere.","punti":[{"titolo":"Un valore vero.","testo":"Ogni variante vale il costo delle mezze giornate di chi l'ha lavorata."},{"titolo":"Mai più del lavoro fatto.","testo":"In una settimana le varianti non possono superare le mezze giornate lavorate sulla commessa."},{"titolo":"Il riepilogo è pronto.","testo":"A fine commessa hai l'elenco con descrizione, giornate e valore. E nel bilancio vedi quante sono rimaste non fatturate."}]},"domande":{"occhiello":"Domande","titolo":"Domande sulle varianti di commessa.","elenco":[{"domanda":"Chi segna le varianti?","risposta":"Il responsabile della commessa, il venerdì, insieme all'avanzamento delle fasi. I collaboratori non devono fare niente di diverso: rispondono come ogni sera."},{"domanda":"Che valore ha una variante?","risposta":"Il costo delle mezze giornate di chi l'ha lavorata. È quanto ti è costata: il prezzo da proporre al cliente lo decidi tu."},{"domanda":"Le varianti cambiano il margine previsto?","risposta":"No. Sono giornate già contate nei costi. Se il cliente le paga e il compenso cresce, aggiorni il compenso e la previsione si ricalcola."},{"domanda":"I collaboratori vedono il valore delle varianti?","risposta":"No. I collaboratori non vedono mai importi: solo le proprie mezze giornate."}]}},"settimana":{"titoloPagina":"Chi lavora su cosa: la settimana dello studio · Clepsi","descrizionePagina":"In una griglia vedi su quali commesse ha lavorato il tuo studio, mezza giornata per mezza giornata, e quale commessa si sta prendendo il tempo delle altre.","nome":"Settimana dello studio","titolo":"Chi ha lavorato su cosa, in una griglia.","titoloEvidenza":"in una griglia.","intro":"Una riga per persona, una casella per ogni mattina e ogni pomeriggio. Con le sigle e i colori delle commesse vedi in un attimo come si è distribuito il lavoro dello studio, e quale commessa si sta mangiando il tempo delle altre.","scheda":{"etichetta":"Esempio della settimana dello studio: quattro persone, cinque giorni, le mezze giornate colorate per commessa. Uffici Lambrate ha preso quasi metà della settimana.","quando":"Settimana 46","sintesi":"Uffici Lambrate si è preso quasi metà della settimana.","giorni":["Lun","Mar","Mer","Gio","Ven"],"persone":[{"chi":"Titolare","celle":["VRO","VRO","ULA","ULA","VRO","SBR","ULA","ULA","STU","STU"]},{"chi":"Socio","celle":["SBR","SBR","SBR","ULA","ULA","ULA","SBR","SBR","ULA","LNA"]},{"chi":"Dipendente","celle":["ULA","ULA","ULA","ULA","VRO","VRO","ULA","ULA","VRO","VRO"]},{"chi":"Collaboratore","celle":["LNA","LNA","VRO","VRO","ASS","ASS","LNA","ULA","ULA","ULA"]}],"giornate":"{n} giornate","legenda":"S attività di studio · – assente"},"lettura":{"occhiello":"Come si legge","titolo":"La settimana del tuo studio, mezza giornata per mezza giornata.","testo":"La griglia si compila da sola con le risposte della sera. Nessuno deve riempire un foglio: ogni casella è un tap.","passi":[{"titolo":"Una casella, una mezza giornata","testo":"Con la sigla e il colore della commessa su cui si è lavorato."},{"titolo":"Due commesse nella stessa mattina","testo":"Si scelgono tutte e due, e la mezza giornata si divide in parti uguali."},{"titolo":"Studio e assenze a parte","testo":"Riunioni, formazione e ferie non pesano su nessuna commessa."}]},"ruoli":{"occhiello":"Chi vede cosa","titolo":"Ognuno vede la sua settimana.","testo":"Il titolare vede la settimana di tutto lo studio. Chi segue una commessa vede le mezze giornate su quella commessa. Chi collabora vede la propria griglia, con i totali in giornate e nessun importo.","punti":[{"titolo":"Correggi fino a domenica.","testo":"Chi collabora può sistemare le proprie risposte della settimana fino a domenica."},{"titolo":"Recuperi i giorni persi.","testo":"Se una sera salta, la domanda si recupera fino a due giorni indietro."},{"titolo":"Nessun importo.","testo":"Nella griglia di chi collabora ci sono solo commesse e giornate."}]},"domande":{"occhiello":"Domande","titolo":"Domande sulla settimana dello studio.","elenco":[{"domanda":"Si può correggere una giornata sbagliata?","risposta":"Sì. Ognuno corregge le proprie mezze giornate fino alla domenica della stessa settimana; chi amministra lo studio può correggerle sempre."},{"domanda":"E se in una mattina ho lavorato su due commesse?","risposta":"Le scegli tutte e due. La mezza giornata si divide in parti uguali: metà per ciascuna, o un terzo se sono tre."},{"domanda":"Come si segnano ferie, riunioni e formazione?","risposta":"Con «Assente» o «Attività di studio»: non vanno su nessuna commessa e non cambiano il margine."},{"domanda":"I collaboratori vedono le giornate degli altri?","risposta":"No. Ognuno vede la propria settimana. Il capo commessa vede le mezze giornate sulle sue commesse, il titolare quelle di tutti."}]}},"bilancio":{"titoloPagina":"Bilancio di commessa e resa per giornata · Clepsi","descrizionePagina":"A fine commessa Clepsi calcola quanto ti ha reso ogni giornata, quante varianti non hai fatturato e come va rispetto alle commesse dello stesso tipo.","nome":"Bilancio di commessa","titolo":"Quanto ti ha reso ogni giornata.","titoloEvidenza":"ogni giornata.","intro":"Quando chiudi una commessa, Clepsi fa il bilancio: le giornate lavorate rispetto a quelle previste, quanto ti ha reso ogni giornata rispetto a quanto ti costa, le varianti rimaste non fatturate. E dopo qualche commessa, la media per tipo di incarico.","contenuto":{"occhiello":"Cosa c'è nel bilancio","titolo":"Cosa c'è nel bilancio di una commessa chiusa.","testo":"Numeri calcolati dalle risposte della sera e da quelle del venerdì. Nessun foglio da compilare a fine lavoro.","passi":[{"titolo":"Giornate lavorate","testo":"Quante ne sono servite davvero, rispetto al budget delle fasi."},{"titolo":"Resa per giornata","testo":"Il compenso meno le spese, diviso le giornate lavorate, confrontato con il costo medio di una giornata dello studio."},{"titolo":"Varianti non fatturate","testo":"Il lavoro in più segnato durante la commessa e non pagato dal cliente."}]},"preventivo":{"occhiello":"Il prossimo preventivo","titolo":"Il prossimo preventivo, sui numeri.","testo":"Commessa dopo commessa, Clepsi mette da parte la resa media per tipo di incarico: ristrutturazioni, nuove costruzioni, direzioni lavori. Quando arriva una richiesta simile sai quanto ti rende davvero, e la parcella la fai su quello.","punti":[{"titolo":"La media per tipo di incarico.","testo":"Quanto rendono in media le commesse chiuse dello stesso tipo."},{"titolo":"Il confronto con il tuo costo.","testo":"Se una giornata ti rende meno di quanto ti costa, lo vedi subito."},{"titolo":"La parcella, prima di iniziare.","testo":"Con il calcolatore gratuito parti dal D.M. 17/06/2016 e la trasformi in commessa."}],"linkParcella":"Calcola la parcella","linkCosto":"Quanto costa una giornata del tuo studio"},"domande":{"occhiello":"Domande","titolo":"Domande sul bilancio di commessa.","elenco":[{"domanda":"Cos'è la resa per giornata?","risposta":"È il compenso meno le spese, diviso le giornate lavorate sulla commessa. Confrontata con il costo medio di una giornata del tuo studio ti dice se quella commessa ti ha fatto guadagnare o perdere."},{"domanda":"Le spese rimborsate dal cliente contano?","risposta":"No. Le spese che il cliente ti rimborsa non entrano nei costi della commessa."},{"domanda":"Quando vedo la media per tipo di incarico?","risposta":"Dalla prima commessa chiusa di quel tipo. Diventa più affidabile a ogni commessa che chiudi."},{"domanda":"Chi vede il bilancio?","risposta":"Chi amministra lo studio e il capo commessa per le sue commesse. Chi collabora non vede importi né margini."}]}},"fatica":{"titoloPagina":"Gestione commesse senza timesheet: due tap la sera · Clepsi","descrizionePagina":"Niente timer e niente ore da segnare: alle 19 il team indica in due tap dove ha lavorato la mattina e il pomeriggio. Dieci secondi, dal telefono.","nome":"Due tap la sera","titolo":"Niente timesheet. Due tap la sera.","titoloEvidenza":"Due tap la sera.","intro":"Negli studi di architettura e ingegneria il timesheet non ha mai funzionato: si compila il venerdì, a memoria, o non si compila. Clepsi chiede una cosa sola, ogni sera alle 19: dove hai lavorato la mattina e dove il pomeriggio.","perche":{"occhiello":"Perché la mezza giornata","titolo":"Perché la mezza giornata e non l'ora.","testo":"Nessuno ricorda se su un progetto ha passato tre ore o tre ore e venti, ma tutti sanno dove hanno lavorato la mattina e dove il pomeriggio. Per sapere il margine di una commessa basta questo.","punti":[{"titolo":"Si ricorda.","testo":"La mattina e il pomeriggio di oggi non si dimenticano: le risposte sono vere."},{"titolo":"Basta per il margine.","testo":"Su settimane e mesi, le mezze giornate bastano per sapere come chiuderà ogni commessa."},{"titolo":"Nessuno si sente cronometrato.","testo":"Niente timer, niente posizione: solo la commessa, scelta da chi ci ha lavorato."}]},"promemoria":{"occhiello":"Se qualcuno si dimentica","titolo":"Una notifica alle 19, un promemoria alle 21.","testo":"La domanda arriva all'orario dello studio, o a quello scelto da ognuno. Chi non ha risposto riceve un promemoria alle 21. E se una sera salta, la si recupera fino a due giorni dopo.","passi":[{"titolo":"Alle 19, la domanda","testo":"Una notifica: «Com'è andata oggi?». Due tap e la giornata è registrata."},{"titolo":"Alle 21, il promemoria","testo":"Solo per chi non ha ancora risposto."},{"titolo":"Fino a due giorni dopo","testo":"Le sere saltate si recuperano senza ricostruire la settimana a memoria."}]},"domande":{"occhiello":"Domande","titolo":"Domande sulla gestione delle commesse senza timesheet.","elenco":[{"domanda":"Quanto tempo ci vuole a rispondere?","risposta":"Meno di dieci secondi: due tap, uno per la mattina e uno per il pomeriggio, e la giornata è registrata."},{"domanda":"Bisogna installare un'app?","risposta":"Sì, chi risponde alla domanda delle 19 usa l'app sul telefono, iPhone o Android. Dal computer si guardano le commesse e si gestisce lo studio."},{"domanda":"È un modo per controllare chi lavora nello studio?","risposta":"No. Niente timer, niente ore, niente posizione: ognuno indica solo la commessa. I collaboratori vedono le proprie giornate, non i compensi né i costi."},{"domanda":"E se in una mezza giornata ho lavorato su più commesse?","risposta":"Le scegli tutte: la mezza giornata si divide in parti uguali tra le commesse scelte."}]}}}`)};function t(e,t={}){return e.replace(/\{(\w+)\}/g,(e,n)=>String(t[n]??`{${n}}`))}export{t as n,e as t};